import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.Di-jvWLj.js";const g=JSON.parse('{"title":"Agent Packages","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent-packages.md","filePath":"guide/agent-packages.md","lastUpdated":1793809847000}'),n={name:"guide/agent-packages.md"};function r(c,e,d,i,l,p){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="agent-packages" tabindex="-1">Agent Packages <a class="header-anchor" href="#agent-packages" aria-label="Permalink to &quot;Agent Packages&quot;">​</a></h1><p>An app can load agents from npm packages by name, next to agents passed in code (<code>createApp({ agents })</code>) and <a href="/guide/agent-folders">agent folders</a>. Ship one agent (or a few) as a package, from a registry or a workspace, and list it in the app:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">import</span><span style="color:#DCE9F2;"> { createApp } </span><span style="color:#8FD0F2;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/app&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">import</span><span style="color:#DCE9F2;"> { triage } </span><span style="color:#8FD0F2;">from</span><span style="color:#E7C58C;"> &#39;./agents/triage.ts&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> default</span><span style="color:#DCE9F2;"> createApp({</span></span>
<span class="line"><span style="color:#DCE9F2;">    agents: [triage, </span><span style="color:#E7C58C;">&#39;@acme/review-agent&#39;</span><span style="color:#DCE9F2;">, </span><span style="color:#E7C58C;">&#39;@acme/agents/digest&#39;</span><span style="color:#DCE9F2;">],</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><p>A string entry is a bare package specifier: a package name, optionally with a subpath it exports. <code>createApp()</code> refuses a relative or absolute path, a URL and a Node builtin (<code>InvalidAgentDefinitionError</code>), and it never touches the file system: the packages are resolved when the app starts.</p><p>Package code runs in the app&#39;s process with the app&#39;s full access, like folder code. Only list packages you would deploy as part of the app.</p><h2 id="listing-packages" tabindex="-1">Listing packages <a class="header-anchor" href="#listing-packages" aria-label="Permalink to &quot;Listing packages&quot;">​</a></h2><p>Three sources, merged in this order (a package listed twice loads once):</p><table tabindex="0"><thead><tr><th>Source</th><th>Form</th></tr></thead><tbody><tr><td><code>createApp({ agents })</code></td><td>string entries beside the agents passed in code</td></tr><tr><td><code>chamvi.json</code></td><td><code>&quot;agents&quot;: [&quot;@acme/review-agent&quot;]</code> (the <a href="/guide/models#the-config-file">config file</a>, <code>CHAMVI_CONFIG_FILE</code> names another one)</td></tr><tr><td><code>CHAMVI_AGENTS</code></td><td>comma-separated specifiers: <code>CHAMVI_AGENTS=@acme/review-agent,@acme/digest-agent</code></td></tr></tbody></table><p>Each specifier resolves from the app&#39;s working directory like Node resolves an <code>import</code> from there: the process&#39;s user conditions (<code>--conditions</code>/<code>-C</code> in its arguments or <code>NODE_OPTIONS</code>) first, then <code>node</code> and <code>import</code>. With <code>NODE_OPTIONS=--conditions=development</code>, a package whose <code>exports</code> list a <code>development</code> target (its <code>src/</code>) before the build output loads that source in dev, its own imports resolve the same way, and the dev revision hashes it. Every listed package must be installed in the app (<code>dependencies</code>, so the image has it). <code>chamvi build</code> keeps the specifiers as strings: nothing of a package is bundled into <code>dist/index.mjs</code>.</p><h2 id="the-package" tabindex="-1">The package <a class="header-anchor" href="#the-package" aria-label="Permalink to &quot;The package&quot;">​</a></h2><p>The package&#39;s entry (the specifier&#39;s <code>exports</code> target) default-exports <code>defineModelAgent()</code>&#39;s or <code>defineSimpleAgent()</code>&#39;s result or a non-empty array of them:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#7F95A6;">// @acme/review-agent, src/index.ts</span></span>
<span class="line"><span style="color:#8FD0F2;">import</span><span style="color:#DCE9F2;"> { defineModelAgent } </span><span style="color:#8FD0F2;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/core&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> default</span><span style="color:#DCE9F2;"> defineModelAgent({</span></span>
<span class="line"><span style="color:#DCE9F2;">    name: </span><span style="color:#E7C58C;">&#39;review&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    instructions: </span><span style="color:#E7C58C;">&#39;Review the pull request.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    tools: { </span><span style="color:#7F95A6;">/* ... */</span><span style="color:#DCE9F2;"> },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><p>The default export may also be a factory: a function, sync or async, called once with no arguments after the import, that returns (or resolves to) an agent or an array of agents. It keeps the import free of side effects and reads the configuration at load. A throw or rejection is a load issue like a failed import (<code>&lt;spec&gt;: the default export&#39;s factory failed: &lt;message&gt;</code>), and <code>start --check</code> calls it too:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> default</span><span style="color:#8FD0F2;"> async</span><span style="color:#8FD0F2;"> function</span><span style="color:#DCE9F2;"> review() {</span></span>
<span class="line"><span style="color:#8FD0F2;">    return</span><span style="color:#DCE9F2;"> createReviewAgent(readConfig(process.env));</span></span>
<span class="line"><span style="color:#DCE9F2;">}</span></span></code></pre></div><ul><li><strong>Peers.</strong> <code>@chamvi/*</code>, <code>ai</code> and <code>@ai-sdk/*</code> always resolve to the app&#39;s copies, also when the package installed copies of its own, so context keys, <code>instanceof</code> checks and the engine are shared. Declare them as <code>peerDependencies</code>.</li><li><strong>Built JavaScript.</strong> A published package ships JavaScript: Node does not strip TypeScript below <code>node_modules</code> (the error says to build the package). A workspace package linked into <code>node_modules</code> may export its <code>.ts</code> source, which Node runs from its real path with its own type stripping, not the transpiler agent folders load through: relative imports name the file with its <code>.ts</code> extension (<code>import &#39;./helper.ts&#39;</code>, TypeScript&#39;s <code>allowImportingTsExtensions</code> or <code>rewriteRelativeImportExtensions</code>; <code>./helper.js</code> and <code>./helper</code> fail), and only erasable syntax works (no <code>enum</code>, <code>namespace</code> or constructor parameter properties).</li><li><strong>Checked like folder agents.</strong> Each agent is checked structurally (another <code>@chamvi/core</code> copy&#39;s agent passes) and rebuilt through the app&#39;s factory of its <code>kind</code> (<code>defineModelAgent()</code> or <code>defineSimpleAgent()</code>), then passes the same checks as a folder agent (channels, cron, MCP, model, skills).</li><li><strong><code>package.json</code> needs a <code>version</code></strong>: it is the agent&#39;s revision (below).</li></ul><h2 id="names" tabindex="-1">Names <a class="header-anchor" href="#names" aria-label="Permalink to &quot;Names&quot;">​</a></h2><p>One agent name, one agent. <strong>Agents passed in code win</strong>, then <strong>packages</strong> (in the merged order), then <strong>folders</strong>. The loser is reported as an issue and never loaded: <code>&lt;name&gt;: an agent passed in code has this name; package &lt;spec&gt; is not loaded.</code>, <code>&lt;name&gt;: package &lt;earlier&gt; already provides this agent; package &lt;spec&gt; is not loaded.</code>, or for a folder <code>&lt;name&gt;: package &lt;spec&gt; provides this agent; the folder is not loaded.</code> A package agent keeps its name against folders once its package loaded, also when its checks or skill preparation then fail. A package that fails to import names no agents, so it reserves only the names whose stored revision is a package marker: on a first deployment, a folder of the name it would export loads.</p><h2 id="revisions" tabindex="-1">Revisions <a class="header-anchor" href="#revisions" aria-label="Permalink to &quot;Revisions&quot;">​</a></h2><p>Like a changed folder, a changed package agent cancels its unsettled runs once across replicas, and a <a href="/guide/agent-folders#jobs-never-reload">job never reloads</a>. A package agent&#39;s revision is its <strong>package version</strong>:</p><ul><li><strong>Production</strong> (<code>chamvi start</code>, <code>run-job</code>, <code>start --check</code>): <code>&lt;name&gt;@&lt;version&gt;</code>, for example <code>@acme/review-agent@1.4.0</code>. Cancel reasons and the <code>agent reloaded</code> log name it in full.</li><li><strong>Dev</strong> (<code>chamvi dev</code>, <code>start --dev</code>): <code>&lt;name&gt;@&lt;version&gt;+&lt;12 hex&gt;</code>, the version plus a hash of the files the package publishes (its <code>files</code> field, else every file but <code>test/</code>; <code>node_modules</code>, dot-files, <code>README*</code>, <code>CHANGELOG*</code> and the other ignored docs left out unless they are JavaScript, <code>package.json</code> without its <code>version</code>) and of the top-level folder of the entry the specifier resolves to (a workspace package exporting <code>src/index.ts</code> while <code>files</code> names <code>dist</code>). Editing those files in an unreleased workspace package cancels its old runs on the next restart; code the entry imports from outside them (a sibling <code>../shared/</code> folder, say) does not move the marker.</li></ul><p>Moving between the dev and the production marker of the same version cancels nothing.</p><p>Trade-offs to plan for:</p><ul><li><strong>Every version bump cancels.</strong> A release that bumps a package&#39;s version cancels its agents&#39; unsettled runs, also when its code did not change. With linked versions (one version for many packages, as release-please&#39;s <code>linked-versions</code> does), every release cancels the runs of every package agent.</li><li><strong>A change without a version bump does not.</strong> In production, new code under an unchanged version keeps the marker, so queued and waiting runs resume on the changed code. Ship tagged releases, never a rebuilt package under the same version.</li></ul><h2 id="removed-agents" tabindex="-1">Removed agents <a class="header-anchor" href="#removed-agents" aria-label="Permalink to &quot;Removed agents&quot;">​</a></h2><p>A package agent that is gone at a start (its package dropped from every list, or a release no longer exports it) is removed like a deleted agent folder: its revision marker is deleted and its unsettled runs are cancelled (<code>agent_removed</code>), with or without an agents dir. The configuration file&#39;s <code>agents</code> are read from the working directory the app runs in, the file the <a href="/guide/models#the-config-file">model settings</a> come from.</p><h2 id="issues" tabindex="-1">Issues <a class="header-anchor" href="#issues" aria-label="Permalink to &quot;Issues&quot;">​</a></h2><p>A package that cannot be resolved, imported or checked never stops the app: it is an issue (<code>agent load failed</code> in the log, <code>GET /agents</code> <code>issues</code>, the dashboard&#39;s notice), and every other agent starts. Resolve, import and check failures are recorded once per process (a package does not change while the app runs); a failed skill preparation is retried with the folders&#39; capped backoff while the app runs. A package that failed before its agents were known is keyed by its specifier: <code>@acme/review-agent: not found from the app&#39;s directory; add it to the app&#39;s dependencies.</code> While one did not load, the start&#39;s boot removes no agent for a revision marker without a folder or package (the marker may belong to the missing package), and an agent folder named like a stored package agent is not loaded (<code>&lt;name&gt;: a package that did not load may provide this agent; the folder is not loaded.</code>), so a broken release never hands the agent and its runs to a folder.</p><ul><li><code>chamvi start --check</code> resolves, imports and checks every package without writing the store; each issue is one stderr line (exit 2).</li><li><code>chamvi run-job &lt;agent&gt;</code> exits 1 (<code>package_agent_failed</code>) when the agent is a package agent that did not load, or when no agent has the name while a package did not load.</li></ul><h2 id="no-hot-reload" tabindex="-1">No hot reload <a class="header-anchor" href="#no-hot-reload" aria-label="Permalink to &quot;No hot reload&quot;">​</a></h2><p>Package agents load once at boot; nothing watches them. <code>chamvi dev</code> restarts the app when an imported file changes (<code>node --watch</code>), which includes a linked workspace package&#39;s source.</p><p>A package the entry imports itself (for example a helper module of the agent package) is loaded before the agents module pins its imports: list such a package by name only, or keep the shared helper in another package.</p>`,31)])])}const m=a(n,[["render",r]]);export{g as __pageData,m as default};
